import React, { useEffect, useState } from "react";

/* =========================
   型定義
========================= */
interface Ranking {
  work_id: number;
  issue_id: number;
  issue_label:string;
  rank_num:number;
  title:string;
}

/* =========================
   コンポーネント
========================= */
const AdminRankingPage: React.FC = () => {
  const [rankings, setRankings] = useState<Ranking[]>([]);
  const [loading, setLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);

  /* -------------------------
     一覧取得
  -------------------------- */
  const fetchRankings = async () => {
    try {
      setLoading(true);
      const res = await fetch("http://localhost:8080/ranking?latest=true");
      if (!res.ok) {
        throw new Error("取得失敗");
      }
      const data: Ranking[] = await res.json();
      setRankings(data);
    } catch (err) {
      setError("データ取得に失敗しました");
    } finally {
      setLoading(false);
    }
  };

console.log(rankings);
  /* -------------------------
     更新処理
  -------------------------- */
  const handleUpdate = async (ranking: Ranking) => {
    try {
      const res = await fetch(`http://localhost:8080/ranking`, {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          rank: ranking.rank_num,
          issue_id: ranking.issue_id,
          work_id: ranking.work_id,
        }),
      });

      if (!res.ok) {
        throw new Error("更新失敗");
      }

      alert("更新しました");
      fetchRankings(); // 再取得
    } catch (err) {
      alert("更新に失敗しました");
    }
  };

  /* -------------------------
     初期ロード
  -------------------------- */
  useEffect(() => {
    fetchRankings();
  }, []);

  // issue単位でグループ化
  const grouped = rankings.reduce<Record<number, Ranking[]>>(
    (acc, cur) => {
      if (!acc[cur.issue_id]) {
        acc[cur.issue_id] = [];
      }
      acc[cur.issue_id].push(cur);
      return acc;
    },
    {}
  );

  /* =========================
     表示
  ========================= */
  return (
    <div style={{ padding: "40px", fontFamily: "sans-serif" }}>
      <h1 style={{ marginBottom: "30px" }}>
        ジャンプ順位 管理画面
      </h1>

      {loading && <p>読み込み中...</p>}
      {error && <p style={{ color: "red" }}>{error}</p>}

      {rankings.map((r) => (
        <div
          key={r.rank_num}
          style={{
            display: "flex",
            gap: "10px",
            marginBottom: "8px",
            alignItems: "center",
          }}
        >
          <span>雑誌号: {r.issue_label}</span>

          <input
            type="number"
            value={r.rank_num}
            min={1}
            onChange={(e) => {
              const newRank = Number(e.target.value);

              setRankings((prev) =>
                prev.map((item) =>
                  item.issue_label === r.issue_label
                    ? { ...item, rank: newRank }
                    : item
                )
              );
            }}
            style={{ width: "60px" }}
          />

          <button onClick={() => handleUpdate(r)}>
            更新
          </button>
        </div>
      ))} {/* rankings */}

 {Object.entries(grouped).map(([issueId, list]) => (
        <div key={issueId} style={{ marginBottom: "40px" }}>
          <h2>【{issueId}号】</h2>

          <table
            style={{
              width: "100%",
              borderCollapse: "collapse",
              marginTop: "10px",
            }}
          >
            <thead>
              <tr style={{ backgroundColor: "#f0f0f0" }}>
                <th style={thStyle}>順位</th>
                <th style={thStyle}>作品名</th>
                <th style={thStyle}>操作</th>
              </tr>
            </thead>

            <tbody>
              {list
                .sort((a, b) => a.rank - b.rank)
                .map((r) => (
                  <tr key={r.work_id}>
                    <td style={tdStyle}>{r.rank}</td>
                    <td style={tdStyle}>{r.work_title}</td>
                    <td style={tdStyle}>
                      <input
                        type="number"
                        value={r.rank}
                        min={1}
                        onChange={(e) => {
                          const newRank = Number(e.target.value);
                          setRankings((prev) =>
                            prev.map((item) =>
                              item.issue_id === r.issue_id &&
                              item.work_id === r.work_id
                                ? { ...item, rank: newRank }
                                : item
                            )
                          );
                        }}
                        style={{
                          width: "60px",
                          marginRight: "10px",
                        }}
                      />
                      <button
                        onClick={() => handleUpdate(r)}
                        style={buttonStyle}
                      >
                        更新
                      </button>
                    </td>
                  </tr>
                ))}
            </tbody>
          </table>
        </div>
      ))}


    </div>
  );
};

export default AdminRankingPage;
